## Submitted testbench
```systemverilog
module tb;
  // ------------------------------------------------------------
  // Clock and reset
  // ------------------------------------------------------------
  logic clk = 1'b0;
  logic rst = 1'b1;

  // ------------------------------------------------------------
  // Configuration
  // ------------------------------------------------------------
  localparam int CLK_PERIOD = 8; // 125 MHz

  // ------------------------------------------------------------
  // DUT port declarations
  // ------------------------------------------------------------
  logic [15:0] prescale = 16'h1;      // drive prescale with a non‑zero value
  logic [7:0]  s_axis_tdata;
  logic        s_axis_tvalid;
  logic        s_axis_tready; // DUT output – leave un‑driven
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready; // DUT input – hold high
  logic        txd;
  logic        rxd;

  // ------------------------------------------------------------
  // Instantiate DUT (uart) with default parameters
  // ------------------------------------------------------------
  uart dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .txd          (txd),
    .tx_busy      (),
    .rx_busy      (),
    .rx_overrun_error(),
    .rx_frame_error(),
    .prescale     (prescale)
  );

  // ------------------------------------------------------------
  // Hold AXI‑stream ready high
  // ------------------------------------------------------------
  assign m_axis_tready = 1'b1;

  // ------------------------------------------------------------
  // Clock generation
  // ------------------------------------------------------------
  initial begin
    clk = 1'b0;
  end
  always #(CLK_PERIOD/2) clk = ~clk;

  // ------------------------------------------------------------
  // Reset sequencing
  // ------------------------------------------------------------
  initial begin
    rst = 1'b1;
    #(CLK_PERIOD*4);
    rst = 1'b0;
    repeat (10) @(negedge clk); // allow DUT to exit reset
  end

  // ------------------------------------------------------------
  // Timing helper tasks
  // ------------------------------------------------------------
  task automatic wait_negedge(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic uart_send_byte(input byte unsigned b);
    int bit_clks = int'(prescale) * 8;
    // start bit
    rxd = 1'b0;
    wait_negedge(bit_clks);
    // data bits, LSB first
    for (int i = 0; i < 8; i = i + 1) begin
      rxd = b[i];
      wait_negedge(bit_clks);
    end
    // stop bit
    rxd = 1'b1;
    wait_negedge(bit_clks);
  endtask

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // wait for reset release
    @(negedge rst);
    // short idle period
    repeat (20) @(negedge clk);

    // drive a single frame that carries the value 0x5A
    uart_send_byte(8'h5A);

    // wait until the receiver presents that value on the AXI output
    wait (m_axis_tvalid && (m_axis_tdata == 8'h5A));

    // coverage point has been hit – end simulation
    $finish;
  end

endmodule
```

